#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gesummv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, x and scalars alpha, beta exactly as in the
 * original PolyBench C version.
 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // Simple but efficient schedule for initialization:
    //  - Vectorize along the innermost (contiguous) dimension.
    //  - Parallelize across outer rows where it helps.
    Target init_target = get_jit_target_from_environment();
    const int vec_width = init_target.natural_vector_size(type_of<num_t>());

    // x is 1D: vectorize across i for good throughput.
    init_x.compute_root()
          .vectorize(i, vec_width);

    // A and B are 2D, stored as (j, i) = (column, row).
    // Rows (i) are independent, and j is contiguous, so:
    init_A.compute_root()
          .parallel(i)          // parallel over rows
          .vectorize(j, vec_width);

    init_B.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide params for alpha and beta so they are proper runtime scalars.
    Param<num_t> alpha_param("alpha_param");
    Param<num_t> beta_param("beta_param");
    alpha_param.set(alpha);
    beta_param.set(beta);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns: use the runtime extent of the first dimension of A.
    RDom j(0, A_param.dim(0).extent(), "j");

    // We implement:
    //   tmp[i] = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    //   y[i] = alpha * tmp[i] + beta * y_acc[i]
    //
    // Using a single fused reduction for better locality:
    //
    //   y[i] = sum_j (alpha * A[i][j] * x[j] + beta * B[i][j] * x[j])
    //
    // This is algebraically equivalent, but avoids storing tmp and y_acc
    // and halves the number of passes over A/B/x.

    Func y_func("y_func");

    // Pure definition: initialize reduction result.
    y_func(i) = cast<num_t>(0);

    // Update definition: accumulate fused contribution from A and B.
    y_func(i) += alpha_param * (A_param(j, i) * x_param(j)) +
                 beta_param  * (B_param(j, i) * x_param(j));

    // -----------------------------------------------
    // Scheduling
    // -----------------------------------------------
    //
    // Data layout:
    //   A, B are stored as (j, i) so j is contiguous in memory.
    //   For each row i, A(j, i) and B(j, i) and x(j) are all
    //   accessed with j as the fast-varying index.
    //
    // We want:
    //   - Parallelism across i (rows) to use many CPU cores.
    //   - Vectorization across j (columns) for SIMD.
    //
    // The reduction has:
    //   y_func(i) = 0
    //   y_func(i) += f(i, j)
    //
    // We:
    //   * compute y_func at root;
    //   * parallelize the pure and update stages over i;
    //   * split and vectorize the reduction RVar j.x.

    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Compute all of y_func at the top level.
    y_func.compute_root();

    // Parallelize across rows for both initialization and reduction.
    y_func.parallel(i);

    // Schedule the update (reduction) step:
    RVar j_outer("j_outer"), j_inner("j_inner");
    y_func.update()
          // Vectorize across contiguous columns j.
          .split(j.x, j_outer, j_inner, vec_width)
          .vectorize(j_inner)
          .parallel(i);

    // Compile the kernel to machine code (separate from timing).
    y_func.compile_jit(target);

    // Measure execution time (only the actual kernel run).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
