void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    // Note: (i % n) is a Halide Expr; Expr(n) lifts 'n' into Halide's type system.
    Expr n_expr = Expr(n);
    init_x(i) = cast<num_t>(i % n_expr) / n_expr;

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>(((i * j + 1) % n_expr)) / n_expr;

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>(((i * j + 2) % n_expr)) / n_expr;

    // Simple but reasonably efficient schedule:
    //  - Parallelize across rows (i) for the 2D matrices.
    //  - Keep x initialization 1D and parallel over i.
    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Dense in j (x dimension), so vectorize j.
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);
    init_B.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_x.compute_root()
          .parallel(i);
    // (We don't also vectorize i for init_x to keep the schedule simple.)

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (the fast dimension of A and B).
    RDom r(0, A.dim(0).extent(), "r");

    // We want to compute:
    //   tmp[i]   = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    //   y[i]     = alpha * tmp[i] + beta * y_acc[i]
    //
    // To improve data locality and reduce memory traffic, we compute
    // both dot-products in a single reduction using a Tuple-valued Func.
    //
    // sums(i)[0] == tmp[i]
    // sums(i)[1] == y_acc[i]
    Func sums("sums");
    {
        Expr zero = cast<num_t>(0);

        // Pure definition: initialize both accumulators to zero.
        sums(i) = Tuple(zero, zero);

        // Update definition over j:
        // sums(i)[0] += A[i][j] * x[j]
        // sums(i)[1] += B[i][j] * x[j]
        Expr a_ij = A_param(r.x, i);
        Expr b_ij = B_param(r.x, i);
        Expr x_j  = x_param(r.x);
        Expr sum0 = sums(i)[0];
        Expr sum1 = sums(i)[1];

        sums(i) = Tuple(sum0 + a_ij * x_j,
                        sum1 + b_ij * x_j);
    }

    // Final combination:
    // y[i] = alpha * sums(i)[0] + beta * sums(i)[1]
    Func y_func("y_func");
    {
        Expr alpha_e = Expr(alpha);
        Expr beta_e  = Expr(beta);
        y_func(i) = alpha_e * sums(i)[0] + beta_e * sums(i)[1];
    }

    // -------------------------
    // Scheduling for performance
    // -------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));
    // Tile size in the i-dimension for parallel work distribution.
    const int tile_i = 64;

    Var io("io"), ii("ii");

    // Compute all rows of the dot-products at root.
    //  - Split i into tiles of size 'tile_i' and parallelize outer tiles (io).
    //  - For each row i, the reduction over r.x walks A(j, i) and B(j, i)
    //    with j as the innermost loop, which is contiguous in memory.
    //  - Vectorize across r.x to get SIMD dot-products.
    sums.compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io);

    // Schedule for the update step (the reduction itself).
    // Parallelize across row tiles, vectorize across the reduction dim r.x.
    sums.update()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(r.x, vec_width);

