    // over i, so we just parallelize across tiles of i.
    Var yo("yo"), yi("yi");
    y_func
        .compute_root()
        .split(i, yo, yi, tile_i)
        .parallel(yo);
    // (We could also vectorize yi here, but the work per element is small
    //  compared to the dot-product, so the impact is minor.)

    // Compile the kernel to machine code for the current target.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
