 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // ------------------------------------------------------------------
    // Scheduling for initialization
    //
    // We parallelize across the slow (row) dimension 'i' and vectorize
    // across the fast (column) dimension 'j' (or across 'i' for init_x).
    // This preserves the original values while improving initialization
    // throughput on multi-core, SIMD-capable CPUs.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // x is 1D; vectorize across i and parallelize over chunks of i.
    init_x
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // A and B are 2D; row 'i' is outer (parallel), column 'j' is inner (vectorized).
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ------------------------------------------------------------------
    // Halide pipeline for GESUMMV
    //
    // Original math:
    //   tmp[i]   = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    //   y[i]     = alpha * tmp[i] + beta * y_acc[i]
    //
    // To preserve floating-point evaluation order exactly, we keep the
    // same per-row accumulation order for each sum, but fuse the two
    // reductions into a single Tuple-valued Func. This lets us walk
    // A and B (and x) only once per row, improving locality and cutting
    // DRAM traffic, while keeping the sequence of operations for each
    // sum identical to the original.
    // ------------------------------------------------------------------

    Var i("i");
    RDom j(0, n, "j");  // j runs over columns (fast dimension)

    // sums(i)[0] will hold tmp[i]
    // sums(i)[1] will hold y_acc[i]
    Func sums("sums");

    // Pure definition: initialize both accumulators to zero.
    sums(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Reduction step over j:
    //   sums(i)[0] += A_param(j, i) * x_param(j);
    //   sums(i)[1] += B_param(j, i) * x_param(j);
    //
    // Using a Tuple update ensures that for a given i, the operations
    // on sums(i)[0] are performed in the same order as the original
    // tmp reduction, and similarly for sums(i)[1] vs y_acc.
    Expr prev_tmp   = sums(i)[0];
    Expr prev_y_acc = sums(i)[1];

    Expr a_ij = A_param(j, i);
    Expr b_ij = B_param(j, i);
    Expr x_j  = x_param(j);

    sums(i) = Tuple(prev_tmp   + a_ij * x_j,
                    prev_y_acc + b_ij * x_j);

    // Final combination:
    // y[i] = alpha * tmp[i] + beta * y_acc[i]
    Func y_func("y_func");
    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    y_func(i) = cast<num_t>(alpha_expr * sums(i)[0] +
                            beta_expr  * sums(i)[1]);

    // ------------------------------------------------------------------
    // Scheduling
    //
    // Data layout:
    //   A_param(j, i), B_param(j, i) with j (columns) contiguous in memory.
    // We keep the inner loop over j to exploit spatial locality in A and B.
    //
    // We parallelize over the outer row dimension i (split into tiles),
    // and leave the reduction over j sequential and cache-friendly.
    // We also vectorize over the inner i tile where it does not disturb
    // the innermost j loop (i.e., we only vectorize pure stages).
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    // Tile size along i (rows). Can be tuned for cache behavior.
    const int i_tile = 64;

    Var i_outer("i_outer"), i_inner("i_inner");

    // sums: initialization (pure definition)
    sums
        .compute_root()
        .split(i, i_outer, i_inner, i_tile)
        .parallel(i_outer)
        .vectorize(i_inner, vec_width);

    // sums: reduction update
    //   Parallelize across row tiles; keep j as innermost loop for
    //   contiguous access to A(j, i) and B(j, i).
    sums
        .update()
        .split(i, i_outer, i_inner, i_tile)
        .parallel(i_outer);
        // We deliberately do *not* vectorize the update here to keep
        // the j loop innermost and fully contiguous in memory.

    // y_func is a simple 1D pure Func; parallelize and vectorize over i.
    y_func
        .compute_root()
        .split(i, i_outer, i_inner, i_tile)
        .parallel(i_outer)
        .vectorize(i_inner, vec_width);

    // Compile the kernel to machine code.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
