    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // -----------------
    // Scheduling for initialization
    // -----------------
    // Use a reasonably aggressive CPU schedule: parallelize across rows
    // and vectorize across the contiguous column dimension.
    Target target = get_host_target();
    Type elem_type = type_of<num_t>();
    int vec_width = target.natural_vector_size(elem_type);
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // 1D initialization of x: split, parallelize outer, vectorize inner.
    {
        Var io("io"), ii("ii");
        init_x
            .compute_root()
            .split(i, io, ii, 256)
            .parallel(io)
            .vectorize(ii, vec_width);
    }

    // 2D initialization of A: parallel over rows (i), vectorize over columns (j).
    {
        Var i_outer("i_outer"), i_inner("i_inner");
        Var j_outer("j_outer"), j_inner("j_inner");
        init_A
            .compute_root()
            // Tile j to create a vectorizable inner loop.
            .split(j, j_outer, j_inner, 256)
            .reorder(j_inner, i, j_outer)
            .parallel(i)
            .vectorize(j_inner, vec_width);
    }

    // Same schedule for B.
    {
        Var i_outer("i_outer_B"), i_inner("i_inner_B");
        Var j_outer("j_outer_B"), j_inner("j_inner_B");
        init_B
            .compute_root()
            .split(j, j_outer, j_inner, 256)
            .reorder(j_inner, i, j_outer)
            .parallel(i)
            .vectorize(j_inner, vec_width);
    }

    // Realize into the provided buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (fast dimension in the Buffer layout).
    RDom j(0, A.dim(0).extent(), "j");

    // tmp[i] = sum_j A[i][j] * x[j]
    // y_acc[i] = sum_j B[i][j] * x[j]
    // y[i] = alpha * tmp[i] + beta * y_acc[i]
    Func tmp("tmp"), y_acc("y_acc"), y_func("y_func");

    // Initialize reductions.
    tmp(i)   = cast<num_t>(0);
    y_acc(i) = cast<num_t>(0);

    // Reduction over j.
    // Use a common subexpression for x[j] so the load can be reused
    // for both A and B accumulations.
    Expr xj = x_param(j);
    tmp(i)   += A_param(j, i) * xj;
    y_acc(i) += B_param(j, i) * xj;

    // Final combination.
    Expr alpha_expr = cast<num_t>(alpha);
    Expr beta_expr  = cast<num_t>(beta);
    y_func(i) = alpha_expr * tmp(i) + beta_expr * y_acc(i);

    // -----------------
    // Scheduling for the main kernel
    // -----------------
    Target target = get_host_target();
    Type elem_type = type_of<num_t>();
    int vec_width = target.natural_vector_size(elem_type);
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // We keep the algorithmic structure (two separate sums followed by
    // the linear combination) to preserve the original numerical
    // behavior, but we tune the loop nest for the host:
    //
    //   - Parallelize across rows (i): rows are independent GEMV operations.
    //   - Vectorize across a block of i to exploit SIMD lanes.
    //
    // tmp and y_acc are left with their default schedule, which means
    // that for each i, their reductions over j are computed on-demand
    // inside the loop over i in y_func. This preserves fusion and
    // keeps the working set to a pair of scalars per row.
    {
        Var io("io"), ii("ii");

        // Tile i into [io][ii]. Each io tile is processed in parallel,
        // and within a tile we vectorize across ii.
        const int i_tile = 128;  // tuneable: rows per parallel tile

        y_func
            .compute_root()
            .split(i, io, ii, i_tile)
            .parallel(io)
            .vectorize(ii, vec_width);
    }

    // Compile the kernel to machine code (outside the timed region).
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
