 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // Common denominator as Expr in the computation type.
    Expr n_expr = cast<num_t>(n);

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / n_expr;

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / n_expr;

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / n_expr;

    // Simple but cache‑friendly / vectorized initialization schedule.
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // x is 1D and contiguous in i.
    init_x
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // A, B: j is the innermost (contiguous) dimension, i is outer.
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // k (column index) runs over 0..n-1; A and B are laid out as (k, i).
    RDom k(0, n, "k");

    // We compute the two independent dot products for each row i in a
    // single reduction using a Tuple to maximize data reuse:
    //
    //   tmp[i]   = sum_k A[i][k] * x[k]
    //   y_acc[i] = sum_k B[i][k] * x[k]
    //
    // and then
    //
    //   y[i] = alpha * tmp[i] + beta * y_acc[i]
    //
    // The order of accumulation for each sum over k matches the
    // original (k from 0 to n-1), so floating‑point roundoff
    // behavior is preserved relative to doing two separate loops.
    Func sums("sums");   // Tuple: (tmp, y_acc)
    Func y_func("y_func");

    // Pure definition: initial values of the two accumulators.
    sums(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Update definition over k: accumulate both dot products together.
    {
        Expr old_tmp   = sums(i)[0];
        Expr old_y_acc = sums(i)[1];

        Expr a_ik = A_param(k, i);
        Expr b_ik = B_param(k, i);
        Expr x_k  = x_param(k);

        sums(i) = Tuple(old_tmp   + a_ik * x_k,
                        old_y_acc + b_ik * x_k);
    }

    // Final combination.
    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);
    y_func(i) = alpha_expr * sums(i)[0] + beta_expr * sums(i)[1];

    // ------------------------------------------------------------------
    // Schedule
    // ------------------------------------------------------------------

    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // We want:
    //   - parallelism across rows i (each row is independent),
    //   - good locality and vectorization across columns k (contiguous),
    //   - minimal temporary storage.
    //
    // We compute y at the root, parallelized over i. For each i, we
    // compute the two dot products in 'sums' locally (one row at a
    // time) and vectorize the inner reduction over k.
    y_func
        .compute_root()
        .parallel(i);

    // Compute the reduction for a single row 'i' at the point where
    // that row of y_func is produced. This keeps only a single row of
    // partial sums live at a time, improving cache behavior and
    // avoiding a large temporary buffer.
    sums
        .compute_at(y_func, i);

    // Vectorize the reduction over k, which is the contiguous
    // (column) dimension of A, B, and x. This gives tight,
    // vectorized loads for A(k, i), B(k, i), and x(k).
    RVar k_r = k.x;
    sums.update()
        .vectorize(k_r, vec_width);

    // ------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------

    // Compile the kernel to machine code (using the chosen Target).
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
